create extension if not exists pg_cron; create schema if not exists academy_internal; create unique index academy_event_division_time on public.academy_events(kind,starts_at,grade); create function academy_internal.announce_trivia() returns void language plpgsql security invoker set search_path=public as $$ declare slot timestamptz; begin slot:=(date_trunc('week',now() at time zone 'America/Detroit')+interval '3 days 19 hours') at time zone 'America/Detroit'; if slot<=now() then slot:=((slot at time zone 'America/Detroit')+interval '7 days') at time zone 'America/Detroit'; end if; insert into academy_events(kind,title,starts_at,grade) values('trivia','Thursday Trivia Night',slot,5),('trivia','Thursday Trivia Night',slot,6) on conflict do nothing; end $$; revoke all on schema academy_internal from public,anon,authenticated; revoke execute on function academy_internal.announce_trivia() from public,anon,authenticated; select academy_internal.announce_trivia(); select cron.schedule('hahn-weekly-trivia-announcement','0 12 * * 1','select academy_internal.announce_trivia();');
